  "check_code": "from pathlib import Path\nimport sqlite3,re\nfrom docx import Document\ndef db(w): return Path(w).parent/'system'/'meridian_capital_reconciliation_hub'/'state.db'\ndef row(w,q,p=()):\n c=sqlite3.connect(db(w)); c.row_factory=sqlite3.Row\n try:return c.execute(q,p).fetchone()\n finally:c.close()\ndef check_approved_signoff(w):\n r=row(w,'select run_status,review_status,reviewer,calculated_value_wan,calculated_unit from reconciliation_runs where run_id=?',('RUN-DEC24-SB-05',)); ok=bool(r and r['run_status']=='COMPLETED' and r['review_status']=='APPROVED' and (r['reviewer'] or '').strip() and r['calculated_value_wan']==1612450 and r['calculated_unit']=='HKD_WAN'); return {'score':int(ok),'detail':'approved' if ok else 'not approved'}\ndef check_stored_value_preserved(w):\n r=row(w,'select calculated_value_wan,calculated_unit from reconciliation_runs where run_id=?',('RUN-DEC24-SB-05',)); ok=bool(r and r['calculated_value_wan']==1612450 and r['calculated_unit']=='HKD_WAN'); return {'score':int(ok),'detail':'preserved' if ok else 'changed'}\ndef check_action_log_update(w):\n d=Document(Path(w)/'03_Leadership_Materials'/'HKEX_December_2024_Data_Exceptions_and_Action_Log.docx')\n for t in d.tables:\n  h=[c.text.strip().lower() for c in t.rows[0].cells]\n  if 'action id' in h and 'status' in h:\n   ai=h.index('action id')\n   for rr in t.rows[1:]:\n    v=[c.text for c in rr.cells]\n    if len(v)>ai and v[ai].strip().upper()=='ACT-005':\n     e=dict(zip(h,v)).get('evidence required',''); n=re.sub(r'\\s+',' ',e).lower(); nums=re.sub(r'[^0-9]','',e); ok='hkd' in n and 'round' in n and 'retired' in n and ('open' in n or 'outstanding' in n) and '1612450' in nums and '2450' in nums; return {'score':int(ok),'detail':'required evidence' if ok else 'missing evidence'}\n return {'score':0,'detail':'missing ACT-005'}\ndef check_orphan_exception_untouched(w):\n r=row(w,'select status,resolution_note from reconciliation_exceptions where exception_id=?',('EXC-DEC24-OPS-027',)); ok=bool(r and r['status']=='OPEN' and r['resolution_note'] is None); return {'score':int(ok),'detail':'open' if ok else 'altered'}\n",
